INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (177, 'schema_resumo', 'Playground: resumo do schema — cada tabela com suas colunas concatenadas (sem params).', 'SQL', 'SELECT TABLE_NAME AS TABELA, GROUP_CONCAT(COLUMN_NAME ORDER BY ORDINAL_POSITION SEPARATOR '', '') AS COLUNAS FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() GROUP BY TABLE_NAME ORDER BY TABLE_NAME', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
